//! Formats of the images the chat shows: same pixels as Pillow's
//! `Image.convert("RGBA")` (first frame), and the same refusal when a file is
//! not a readable image.
//!
//! Fixtures: `tests/data/chat_images/` (generated by `generate.py` with the
//! Pillow of the Python venv; each image has its `.rgba` next to it).

use std::path::Path;

use ez_hud::paint::chat::imaging::decode;

const DATA: &str = "tests/data/chat_images";

/// Formats with an exact decoder: they must match Pillow byte for byte.
const EXACT: [&str; 9] = [
    "gradiente.png",
    "gradiente.gif",
    "transparente.gif",
    "animado.gif",
    "gradiente.bmp",
    "alfa.bmp",
    "gradiente.webp",
    "perdida.webp",
    "animado.webp",
];

/// JPEG decoders differ in the IDCT and in chroma upsampling (Pillow uses
/// libjpeg-turbo, `image` uses zune-jpeg): a few units per channel, never a
/// different picture (a channel swap or a wrong size would be off by 100+).
const JPEG_MAX_DELTA: u8 = 8;

fn load(name: &str) -> (Vec<u8>, Vec<u8>) {
    let image = std::fs::read(Path::new(DATA).join(name)).expect("imagen de prueba");
    let expected = std::fs::read(Path::new(DATA).join(format!("{name}.rgba")))
        .expect("RGBA esperado de Pillow");
    (image, expected)
}

/// Largest per-channel absolute difference, alpha included.
fn max_delta(actual: &[u8], expected: &[u8]) -> u8 {
    assert_eq!(actual.len(), expected.len(), "mismo tamaño que Pillow");
    actual
        .iter()
        .zip(expected)
        .map(|(left, right)| left.abs_diff(*right))
        .max()
        .expect("algún canal")
}

#[test]
fn exact_formats_match_pillow() {
    for name in EXACT {
        let (bytes, expected) = load(name);
        let image = decode(&bytes).unwrap_or_else(|error| panic!("{name}: {error}"));
        assert_eq!(
            image.width() as usize * image.height() as usize * 4,
            expected.len(),
            "{name}: tamaño"
        );
        assert_eq!(image.as_raw(), expected.as_slice(), "{name}: píxeles");
    }
}

#[test]
fn jpeg_stays_within_its_decoder_tolerance() {
    let (bytes, expected) = load("gradiente.jpg");
    let image = decode(&bytes).expect("JPEG legible");
    assert_eq!((image.width(), image.height()), (8, 6));
    let delta = max_delta(image.as_raw(), &expected);
    assert!(delta <= JPEG_MAX_DELTA, "delta máximo {delta}");
}

#[test]
fn a_corrupt_or_unknown_file_is_refused() {
    for bytes in [
        b"no soy una imagen".as_slice(),
        b"BM".as_slice(),
        b"\x89PNG\r\n\x1a\n".as_slice(),
    ] {
        assert!(decode(bytes).is_err(), "no debería decodificar");
    }
}
